def has_path(coll, path):
    """Returns True if the nested collection contains a value at the given path.

    Path is a sequence of keys/indices. The function traverses the collection
    and returns True if every key/index exists. It returns False if any
    key/index is missing.
    """
    for key in path:
        try:
            coll = coll[key]
        except (KeyError, IndexError, TypeError):
            return False
    return True
